// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 collectAmount, uint256 collectLock, uint256 newMin) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= collectAmount);
        try c.Collect(collectAmount) {} catch { return; }
        bool reverted;
        try c.SetMinSum(newMin) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted == false);
    }

    function testFuzz_run(uint256 collectAmount, uint256 collectLock, uint256 newMin) public {
        _run(collectAmount, collectLock, newMin);
    }

    receive() external payable {}
}
